let captureBlocked=false,lockTimer=null;
let cloud=null,cloudMessage='Conectando respaldo…',cloudRestoreHead=null;
let lastSavedSaleId='';
let s=CafeDemo.seed(),ready=false,busy=false,revision=0,storageError='',saleCategory='all',reportFilters={},accountFilter='pending',tab='Venta',cart={},selected='a',filter='pending',group='all',mode='cash',cashStudent='',saleToken=null,paymentToken=null,doc=null,editingProduct='',editingStudent='',removing=null,menuCategory='food',menuForm='',saleFilters={level:'',grade:'',group:'',search:''};
const LEVELS={kinder:'Kínder',primaria:'Primaria',secundaria:'Secundaria',preparatoria:'Preparatoria'};
function levelOptions(value='',all=false){return `<option value="">${all?'Todos':'Seleccionar nivel'}</option>`+(all?`<option value="undefined" ${value==='undefined'?'selected':''}>Sin definir</option>`:'')+Object.entries(LEVELS).map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('');}
function studentGroup(a){return (LEVELS[a.level]||'Sin definir')+' · '+a.group;}
const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:s.config.currency}).format(n/100),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),token=()=>globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)+Date.now().toString(36);
function note(t){$('toast').textContent=t}function saldo(n){return n>0?money(n)+' por pagar':n<0?money(-n)+' a favor':'Al corriente'}function student(){return s.students.find(a=>a.id===selected)}function activeStudents(){return s.students.filter(a=>!a.archived)}function items(){return s.products.filter(p=>!p.archived&&cart[p.id]).map(p=>({...p,qty:cart[p.id]}))}function amount(){return items().reduce((n,p)=>n+p.price*p.qty,0)}
function nav(to){if(!ready||busy)return;if(cloudRestoreHead!==null&&to!=='Ajustes')cancelCloudRestore();if(tab==='Menú'&&menuDirty&&!globalThis.confirm('Hay datos sin guardar. ¿Salir y descartarlos?'))return;if(tab==='Menú'){menuDirty=false;menuForm='';}if(!s.config.initialized&&to!=='Ajustes'){note('Primero guarda la configuración de la cafetería.');return;}tab=to;doc=null;note('');render()}function button(text,action,style=''){return `<button class="${style}" onclick="${action}">${text}</button>`}function title(k,t){return `<span class="eyebrow">${k}</span><h1>${t}</h1>`}
function navIcon(name){const paths={Venta:'M3 4h2l2 12h11l3-8H6 M9 20h.01 M18 20h.01',Caja:'M3 5h18v14H3z M3 9h18 M15 14h3',Alumnos:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87','Menú':'M4 3h12v18H4z M8 7h4 M8 11h4 M8 15h4 M16 7h4v14h-4',Reportes:'M4 20V10 M10 20V4 M16 20v-7 M2 20h20',Ajustes:'M4 7h16 M4 17h16 M8 4v6 M16 14v6'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]}"/></svg>`;}
function render(){if(!ready)return;const names=['Venta','Caja','Alumnos','Menú','Reportes','Ajustes'];const section=tab==='EditarAlumno'?'Alumnos':tab==='EditarProducto'?'Menú':tab==='Eliminar'?(removing?.kind==='product'?'Menú':'Alumnos'):['Cuenta','Pago','Documento','PeriodoDocumento','Correccion','Devolucion','SaldoInicial'].includes(tab)?'Reportes':tab;$('nav').innerHTML=names.map(n=>`<button class="nav-item ${section===n?'active':''}" ${section===n?'aria-current="page"':''} onclick="nav('${n}')">${navIcon(n)}<span>${n}</span></button>`).join('');$('screen').innerHTML=({Venta:saleScreen,Cuenta:accountScreen,Pago:paymentScreen,Documento:documentScreen,Alumnos:studentsScreen,Menú:menuScreen,Reportes:reportsScreen,Ajustes:settingsScreen,PeriodoDocumento:documentPeriodScreen,Caja:cashScreen,Correccion:correctionScreen,Devolucion:refundScreen,SaldoInicial:openingScreen,EditarProducto:productEditScreen,EditarAlumno:studentEditScreen,Eliminar:removeScreen})[tab]();}
function recentSales(){const sales=s.events.filter(e=>['cash','sale'].includes(e.kind)).slice().reverse(),last=sales.find(e=>e.id===lastSavedSaleId),receipt=last?`<div id="saleReceipt" class="sale-receipt" role="status" aria-live="polite" tabindex="-1"><span class="receipt-check" aria-hidden="true">✓</span><div><strong>Venta guardada · ${money(last.total)}</strong><span>Ya aparece en el historial. Puedes iniciar otra venta.</span></div></div>`:'';return receipt+`<section class="card recent-sales" aria-label="Ventas recientes"><div class="history-heading"><h2>Ventas recientes</h2>${button('Ver todas',"nav('Reportes')",'plain')}</div>${sales.slice(0,3).map(e=>`<div class="recent-sale ${e.id===lastSavedSaleId?'just-saved':''}"><div class="row"><strong>${esc(e.studentSnapshot?.name||s.students.find(a=>a.id===e.student)?.name||'Sin alumno')}</strong><strong>${money(e.total)}</strong></div><span class="pill">${CafeDemo.reversed(s,e.id)?'Anulada':e.kind==='sale'?'A cuenta del alumno':e.method==='transfer'?'Pagada · transferencia':'Pagada · efectivo'}</span><span class="small"> · ${esc(e.date)}${e.occurredAt?' · '+esc(new Intl.DateTimeFormat('es-MX',{hour:'2-digit',minute:'2-digit',timeZone:s.config.timezone}).format(new Date(e.occurredAt))):''}</span><p class="muted">${e.items.map(i=>`${i.qty} × ${esc(i.name)}`).join(' · ')}</p></div>`).join('')||'<p class="muted">Todavía no hay ventas. Al confirmar, tu venta aparecerá aquí.</p>'}</section>`;}

function saleScreen(){return recentSales()+title('Durante el despacho','Nueva venta')+cashStatus()+`<p class="muted">Toca un producto para agregarlo.</p><label>Categoría</label><select onchange="saleCategory=this.value;render()"><option value="all">Todas</option>${s.categories.map(c=>`<option value="${c.id}" ${saleCategory===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div class="products">${s.products.filter(p=>!p.archived&&(saleCategory==='all'||p.categoryId===saleCategory)).map(p=>`<button class="product" onclick="add('${p.id}',1)"><strong>${esc(p.name)}</strong><span>${money(p.price)}</span></button>`).join('')}</div><div class="card"><h2>Esta compra</h2>${items().map(p=>`<div class="row"><div>${esc(p.name)}<br><span class="muted">${money(p.price)} cada uno</span></div><div class="qty">${button('−',`add('${p.id}',-1)`)}<strong>${p.qty}</strong>${button('+',`add('${p.id}',1)`)}</div></div>`).join('')||'<p class="muted">Todavía no hay productos.</p>'}<div class="row"><strong>Total</strong><span class="total">${money(amount())}</span></div></div><button class="full" onclick="prepareSale()" ${!amount()?'disabled':''}>Continuar · Elegir cómo registrar</button>`;}
function add(id,n){if(!ready||busy)return;cart[id]=Math.max(0,(cart[id]||0)+n);render()}
function prepareSale(){if(!ready||busy||!amount())return;if(!CafeDemo.active(s)){note('Abre caja antes de registrar ventas.');tab='Caja';render();return;}saleToken=token();mode='cash';selected='';cashStudent='';saleMethod='cash';saleFilters={level:'',grade:'',group:'',search:''};showSaleConfirmation();}
function normalizeName(v){return v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').trim();}
function saleCandidates(){return activeStudents().filter(a=>(a.level||'undefined')===saleFilters.level&&String(a.grade??'undefined')===saleFilters.grade&&(a.groupLetter||a.group)===saleFilters.group&&normalizeName(a.name).includes(normalizeName(saleFilters.search))).sort((a,b)=>a.name.localeCompare(b.name,'es'));}
function saleFilter(field,value){if(busy)return;saleFilters[field]=value;if(field==='level'){saleFilters.grade='';saleFilters.group='';}if(field==='grade')saleFilters.group='';saleFilters.search='';selected='';cashStudent='';showSaleConfirmation();}
function pickSaleStudent(id){if(busy)return;if(id&&!saleCandidates().some(a=>a.id===id)){note('Selecciona un alumno del grupo elegido.');return;}if(mode==='sale')selected=id;else cashStudent=id;showSaleConfirmation();}
function searchSaleStudent(value){saleFilters.search=value;const chosen=mode==='sale'?selected:cashStudent;if(chosen&&!saleCandidates().some(a=>a.id===chosen)){selected='';cashStudent='';if($('saleStudentSummary'))$('saleStudentSummary').style.display='none';if($('saleStudentBalance'))$('saleStudentBalance').style.display='none';}showSaleStudentOptions();}
function saleStudentOptions(){const chosen=mode==='sale'?selected:cashStudent;return '<option value="">'+(mode==='sale'?'Seleccionar alumno':'Sin alumno')+'</option>'+saleCandidates().map(a=>`<option value="${a.id}" ${chosen===a.id?'selected':''}>${esc(a.name)} · ${esc(a.id.slice(-5))}</option>`).join('');}
function showSaleStudentOptions(){const node=$('saleStudent');if(node)node.innerHTML=saleStudentOptions();$('finishSaleButton').disabled=mode==='sale'&&!selected;}
function studentPicker(){const f=saleFilters,levels=[...new Set(activeStudents().map(a=>a.level||'undefined'))],byLevel=activeStudents().filter(a=>(a.level||'undefined')===f.level),grades=[...new Set(byLevel.map(a=>String(a.grade??'undefined')))].sort((a,b)=>a.localeCompare(b,'es',{numeric:true})),groups=[...new Set(byLevel.filter(a=>String(a.grade??'undefined')===f.grade).map(a=>a.groupLetter||a.group))].sort();return `<div class="card"><h2>${mode==='sale'?'Elegir alumno':'Asociar alumno (opcional)'}</h2><label>Nivel educativo</label><select onchange="saleFilter('level',this.value)"><option value="">Seleccionar nivel</option>${levels.map(v=>`<option value="${v}" ${f.level===v?'selected':''}>${LEVELS[v]||'Sin definir'}</option>`).join('')}</select><div class="two"><div><label>Grado</label><select ${!f.level?'disabled':''} onchange="saleFilter('grade',this.value)"><option value="">Seleccionar grado</option>${grades.map(v=>`<option value="${v}" ${f.grade===v?'selected':''}>${v==='undefined'?'Sin definir':v+'°'}</option>`).join('')}</select></div><div><label>Grupo</label><select ${!f.grade?'disabled':''} onchange="saleFilter('group',this.value)"><option value="">Seleccionar grupo</option>${groups.map(v=>`<option value="${esc(v)}" ${f.group===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div></div><label>Buscar en este grupo</label><input id="saleStudentSearch" ${!f.group?'disabled':''} value="${esc(f.search)}" placeholder="Nombre o apellidos" oninput="searchSaleStudent(this.value)"><label>Alumno · ${f.group?saleCandidates().length:0} disponibles</label><select id="saleStudent" ${!f.group?'disabled':''} onchange="pickSaleStudent(this.value)">${saleStudentOptions()}</select>${f.group&&!saleCandidates().length?'<p class="notice">No hay alumnos con estos filtros.</p>':''}</div>`;}
function changeSaleMode(value){mode=value;selected='';cashStudent='';showSaleConfirmation();}
function showSaleConfirmation(){const a=mode==='sale'?student():s.students.find(a=>a.id===cashStudent),prior=a?CafeDemo.balance(s,a.id):0;$('screen').innerHTML=title('Revisar antes de guardar','Confirmar venta')+`<div class="card"><span class="muted">Total de la compra</span><div class="bigbalance">${money(amount())}</div>${items().map(p=>`<div class="row"><span>${p.qty} × ${esc(p.name)}</span><strong>${money(p.qty*p.price)}</strong></div>`).join('')}</div><label>¿Cómo se registra?</label><select onchange="changeSaleMode(this.value)"><option value="cash" ${mode==='cash'?'selected':''}>Pagado ahora</option><option value="sale" ${!activeStudents().length?'disabled':''} ${mode==='sale'?'selected':''}>A la cuenta del alumno</option></select>${mode==='cash'?methodFields('saleMethod',saleMethod):''}${studentPicker()}${a?`<p id="saleStudentSummary"><strong>${esc(a.name)}</strong> · ${esc(studentGroup(a))}</p>`:''}${mode==='sale'&&a?`<div class="card" id="saleStudentBalance"><div class="row"><span>Antes de esta compra</span><strong>${saldo(prior)}</strong></div><div class="row"><span>Después</span><strong>${saldo(prior+amount())}</strong></div></div><p class="muted">Se usa el saldo a favor existente. No se registra otro pago.</p>`:mode==='cash'?`<div class="card"><strong>Pago recibido: ${money(amount())}</strong><p class="muted">No cambia ninguna deuda anterior. Asociar alumno es opcional.</p></div>`:''}<div class="actions">${button('Volver','render()','secondary')}<button id="finishSaleButton" onclick="finishSale()" ${mode==='sale'&&!selected?'disabled':''}>Confirmar y guardar</button></div>`;}
async function finishSale(){if(!CafeDemo.active(s)){note('Abre caja antes de registrar ventas.');return;}if(mode==='sale'&&!selected){note('Selecciona al alumno antes de confirmar.');return;}const id=mode==='sale'?selected:(cashStudent||null),a=s.students.find(x=>x.id===id);const event={id:saleToken,kind:mode,student:id,method:mode==='cash'?saleMethod:null,sessionId:CafeDemo.active(s).id,studentSnapshot:a?{name:a.name,level:a.level||null,grade:a.grade,group:a.group,cycle:s.config.cycle}:null,items:items(),date:operationDate(),occurredAt:new Date().toISOString()};await commit(draft=>CafeDemo.post(draft,event),()=>{cart={};tab='Venta';lastSavedSaleId=event.id;},'Venta guardada en este dispositivo.');if(tab==='Venta'&&lastSavedSaleId===event.id){$('saleReceipt').scrollIntoView?.({block:'start',behavior:'instant'});$('saleReceipt').focus?.({preventScroll:true});}}
function openAccount(id){selected=id;tab='Cuenta';render();note('')}
function accountRows(id){const a=s.students.find(x=>x.id===id);return [{label:'Saldo inicial anterior',amount:a.opening},...s.events.filter(e=>e.student===id&&e.kind!=='cash'&&e.kind!=='refund-cash').map(e=>({id:e.id,label:CafeDemo.eventLabel(e,s)+' · '+e.date,amount:CafeDemo.signed(e,s)}))];}
function accountScreen(){const a=student(),b=CafeDemo.balance(s,selected);return title(esc(studentGroup(a)),esc(a.name))+`<div class="card"><span class="muted">Saldo al corte</span><div class="bigbalance ${b>0?'debt':'credit'}">${money(Math.abs(b))}</div><strong>${b>0?'Por pagar':b<0?'A favor':'Al corriente'}</strong></div><div class="two">${button('Registrar pago / anticipo',"startPayment()")}${button('Ver documento',"makeDoc()",'secondary')}</div>${b<0?button('Devolver saldo a favor',"startRefund('credit',selected)",'secondary'):''}<div class="card"><h2>Movimientos</h2>${accountRows(selected).map(r=>`<div class="row"><span>${esc(r.label)}</span><strong>${r.amount<0?'−':''}${money(Math.abs(r.amount))}</strong></div>${r.id&&['sale','payment','opening'].includes(s.events.find(e=>e.id===r.id)?.kind)&&!CafeDemo.reversed(s,r.id)?button('Corregir / anular',`startCorrection('${r.id}')`,'plain'):''}`).join('')}</div>${button('Volver a reportes',"nav('Reportes')",'plain')}`;}
let paymentDraft={amount:'',method:'cash',note:''},paymentAmount=0,saleMethod='cash';
function methodFields(id,value){return `<label>Método</label><select id="${id}" onchange="${id==='saleMethod'?'saleMethod=this.value':''}"><option value="cash" ${value==='cash'?'selected':''}>Efectivo</option><option value="transfer" ${value==='transfer'?'selected':''}>Transferencia confirmada</option></select>`;}
function startPayment(){if(!CafeDemo.active(s)){note('Abre caja antes de registrar cobros.');return;}paymentToken=token();paymentDraft={amount:'',method:'cash',note:''};nav('Pago');}
function cents(raw,zero=false){if(!/^\d+(\.\d{1,2})?$/.test(raw))throw Error('Usa un importe válido con hasta dos decimales.');const n=Math.round(Number(raw)*100);if(!Number.isSafeInteger(n)||n<(zero?0:1))throw Error('Revisa el importe.');return n;}
function paymentScreen(){return title('Pago o anticipo',esc(student().name))+`<p class="muted">Hoy: ${saldo(CafeDemo.balance(s,selected))}.</p><label>Importe recibido (${s.config.currency})</label><input id="paymentAmount" type="number" min="0.01" step="0.01" value="${esc(paymentDraft.amount)}">${methodFields('payMethod',paymentDraft.method)}<label>Nota / referencia (opcional)</label><input id="paymentNote" value="${esc(paymentDraft.note)}"><p class="notice">El pago cubre los cargos más antiguos. Lo que sobre queda a favor.</p><div class="actions">${button('Volver',"nav('Cuenta')",'secondary')}${button('Revisar pago','reviewPayment()')}</div>`;}
function reviewPayment(){paymentDraft={amount:$('paymentAmount').value,method:$('payMethod').value,note:$('paymentNote').value.trim()};try{paymentAmount=cents(paymentDraft.amount);}catch(e){note(e.message);return;}const before=CafeDemo.balance(s,selected);$('screen').innerHTML=title('Antes de confirmar','Revisar pago')+`<p>${esc(student().name)} · ${esc(studentGroup(student()))}</p><div class="card"><div class="row"><span>Recibido</span><strong>${money(paymentAmount)}</strong></div><div class="row"><span>Antes</span><strong>${saldo(before)}</strong></div><div class="row"><span>Después</span><strong>${saldo(before-paymentAmount)}</strong></div><p>${paymentDraft.method==='cash'?'Efectivo':'Transferencia confirmada'} · ${esc(paymentDraft.note)}</p></div><div class="actions">${button('Corregir','render()','secondary')}${button('Confirmar y guardar',`finishPayment(${paymentAmount})`)}</div>`;}
async function finishPayment(n){if(!CafeDemo.active(s)){note('Abre caja antes de registrar cobros.');return;}const event={id:paymentToken,kind:'payment',student:selected,total:n,method:paymentDraft.method,note:paymentDraft.note,sessionId:CafeDemo.active(s).id,date:operationDate(),occurredAt:new Date().toISOString()};await commit(draft=>CafeDemo.post(draft,event),()=>{tab='Cuenta';},'Pago guardado en este dispositivo.');}
let docToken='',docPeriod={from:'',to:''};
function todayISO(){return CafeDemo.day({occurredAt:new Date().toISOString()},s.config.timezone);}
function makeDoc(){docToken=token();docPeriod={from:reportFilters.from||'',to:reportFilters.to||todayISO()};tab='PeriodoDocumento';render();note('');}
function documentPeriodScreen(){return title('Cuenta individual',esc(student().name))+`<label>Desde (vacío: desde el inicio)</label><input id="docFrom" type="date" value="${esc(docPeriod.from)}" max="${todayISO()}"><label>Corte / hasta</label><input id="docTo" type="date" value="${esc(docPeriod.to)}" max="${todayISO()}"><p class="muted">El documento incluye saldo anterior al periodo y saldo completo al corte. Guardarlo no cobra ni liquida la cuenta.</p><div class="actions">${button('Ver vista previa','previewDocument()')}${button('Volver',"nav('Cuenta')",'secondary')}</div><h2>Documentos emitidos</h2>${s.documents.filter(d=>d.student===selected).slice().reverse().map(d=>button(esc(d.folio)+' · '+esc(d.to)+' · v'+d.version,`openDocument('${d.id}')`,'secondary')).join('')||'<p class="muted">Sin emisiones anteriores.</p>'}`;}
function previewDocument(){docPeriod={from:$('docFrom').value,to:$('docTo').value};if(!docPeriod.to||docPeriod.to>todayISO()||docPeriod.from&&docPeriod.from>docPeriod.to){note('Revisa las fechas: el corte no puede ser futuro ni anterior al inicio.');return;}try{const tmp=JSON.parse(JSON.stringify(s));CafeDemo.issue(tmp,{id:docToken,student:selected,...docPeriod,issuedAt:new Date().toISOString()});doc={...tmp.documents.at(-1),preview:true};tab='Documento';render();}catch(e){note(e.message);}}
async function emitDocument(){const data={id:docToken,student:doc.student,from:doc.from,to:doc.to,issuedAt:doc.issuedAt};await commit(d=>CafeDemo.issue(d,data),()=>{doc=s.documents.find(d=>d.id===docToken);tab='Documento';},'Documento emitido y conservado en este dispositivo.');}
function openDocument(id){doc=s.documents.find(d=>d.id===id);tab='Documento';render();}
function documentScreen(){if(!doc)return '';const d=doc,c=d.business,dm=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:c.currency}).format(n/100);return title(d.preview?'Vista previa':'Emisión conservada','Cuenta individual')+`<article class="paper" id="paper"><span class="eyebrow">${esc(c.name)}</span><p class="small">${esc(c.school)}${c.location?' · '+esc(c.location):''}</p><h2>Resumen de cuenta</h2><strong>${esc(d.name)}</strong><p>${LEVELS[d.level]||'Sin definir'} · ${esc(d.group)} · Moneda: ${c.currency}<br>Periodo: ${d.from?esc(d.from):'Desde el inicio'} al ${esc(d.to)}<br>${d.preview?'Vista previa sin emitir':esc(d.folio)+' · versión '+d.version}<br>Emisión: ${esc(new Date(d.issuedAt).toLocaleString('es-MX',{timeZone:c.timezone}))}</p><table><thead><tr><th>Movimiento</th><th>Importe</th></tr></thead><tbody><tr><td>Saldo anterior ${d.previous<0?'a favor':''}</td><td>${d.previous<0?'−':''}${dm(Math.abs(d.previous))}</td></tr>${d.rows.map(r=>`<tr><td>${esc(r.date||'')} · ${esc(r.label)}</td><td>${r.amount<0?'−':''}${dm(Math.abs(r.amount))}</td></tr>`).join('')}</tbody></table><div class="row"><strong>${d.balance>0?'Saldo por pagar':d.balance<0?'Saldo a favor':'Saldo'}</strong><span class="total">${dm(Math.abs(d.balance))}</span></div><p class="small">Documento operativo. No es factura.</p></article><div class="actions">${button('Volver',"tab='PeriodoDocumento';render()",'secondary')}${d.preview?button('Emitir y guardar documento','emitDocument()'):button('Imprimir / guardar PDF','window.print()')}</div><p class="muted">La impresión o el PDF conserva esta emisión. Una corrección posterior requiere una nueva versión. Compartir el PDF se hace manualmente desde el teléfono.</p>`;}
function studentsScreen(){const active=activeStudents();let list='';for(const level of [...Object.keys(LEVELS),'']){const pupils=active.filter(a=>(a.level||'')===level);if(!pupils.length)continue;const groups=[...new Set(pupils.map(a=>a.group))].sort((a,b)=>a.localeCompare(b,'es',{numeric:true}));list+=`<details class="card"><summary><strong>${LEVELS[level]||'Sin definir'}</strong> · ${pupils.length} alumnos · ${groups.length} grupos</summary>${groups.map(g=>{const members=pupils.filter(a=>a.group===g).sort((a,b)=>a.name.localeCompare(b.name,'es'));return `<details class="card"><summary><strong>${esc(g)}</strong> · ${members.length} alumnos</summary>${members.map(a=>`<div class="catalog-item"><strong>${esc(a.name)}</strong><div class="actions">${button('Ver cuenta',`openAccount('${a.id}')`,'secondary')}${button('Editar',`editStudent('${a.id}')`,'secondary')}${button('Eliminar',`requestRemove('student','${a.id}')`,'danger')}</div></div>`).join('')}</details>`}).join('')}</details>`;}return title('Organizar alumnos','Alumnos por nivel y grupo')+(list||'<p class="muted">Todavía no hay alumnos activos.</p>')+`<div class="card"><h2>Agregar alumno</h2><label>Nombre(s)</label><input id="newName" placeholder="Nombre(s) del alumno"><label>Apellidos</label><input id="newSurnames" placeholder="Apellidos del alumno"><label>Nivel educativo</label><select id="newLevel">${levelOptions()}</select><div class="two"><div><label>Grado</label><select id="newGrade">${[1,2,3,4,5,6].map(g=>`<option value="${g}">${g}°</option>`).join('')}</select></div><div><label>Grupo</label><select id="newGroup">${['A','B','C','D','E','F'].map(g=>`<option>${g}</option>`).join('')}</select></div></div><div class="actions">${button('Guardar alumno','addStudent()')}</div></div>`;}
async function addStudent(){const firstName=$('newName').value.trim(),surnames=$('newSurnames').value.trim(),level=$('newLevel').value,name=[firstName,surnames].filter(Boolean).join(' '),grade=Number($('newGrade').value),groupLetter=$('newGroup').value;if(!firstName||!surnames||!LEVELS[level]||!Number.isInteger(grade)||grade<1||grade>6||!/^[A-F]$/.test(groupLetter)){note('Revisa nombre(s), apellidos, nivel educativo, grado y grupo.');return;}const alumno={id:token(),name,firstName,surnames,level,grade,groupLetter,group:grade+'° '+groupLetter,opening:0};await commit(draft=>{draft.students.push(alumno);},()=>{if(!selected)selected=alumno.id;},'Alumno guardado en este dispositivo.');}
async function saveStudentDetails(){if(tab!=='EditarAlumno'||!editingStudent){note('Edita los datos desde Alumnos → Editar.');return;}const id=editingStudent,firstName=$('editFirstName').value.trim(),surnames=$('editSurnames').value.trim(),level=$('editLevel').value,grade=Number($('editGrade').value),groupLetter=$('editGroup').value;if(!firstName||!surnames||!LEVELS[level]||!Number.isInteger(grade)||grade<1||grade>6||!/^[A-F]$/.test(groupLetter)){note('Completa nombre(s), apellidos, nivel, grado y grupo.');return;}await commit(draft=>{const a=draft.students.find(x=>x.id===id);if(!a)throw Error('Alumno no encontrado.');Object.assign(a,{firstName,surnames,name:firstName+' '+surnames,level,grade,groupLetter,group:grade+'° '+groupLetter});},()=>{tab='Alumnos';},'Datos del alumno guardados.');}
function menuScreen(){if(!s.categories.some(c=>c.id===menuCategory))menuCategory=s.categories[0]?.id;const c=s.categories.find(c=>c.id===menuCategory);return title('Catálogo','Menú por categorías')+`<div class="category-tabs" aria-label="Categorías">${s.categories.map(c=>`<button aria-pressed="${menuCategory===c.id}" class="${menuCategory===c.id?'':'secondary'}" onclick="selectMenuCategory('${c.id}')">${esc(c.name)}</button>`).join('')}</div><div class="card"><h2>${esc(c?.name||'Menú')}</h2>${s.products.filter(p=>!p.archived&&p.categoryId===menuCategory).map(p=>`<div class="catalog-item"><div class="row"><div><strong>${esc(p.name)}</strong>${p.description?'<br><span class="muted">'+esc(p.description)+'</span>':''}<br><span class="muted">${p.initialStock==null?'Existencia sin registrar':'Conteo inicial: '+p.initialStock+' piezas · '+esc(p.stockCountedAt.slice(0,10))}</span></div><span>${money(p.price)}</span></div><div class="actions">${button('Editar',`editProduct('${p.id}')`,'secondary')}${button('Eliminar',`requestRemove('product','${p.id}')`,'danger')}</div></div>`).join('')||'<p class="muted">Sin productos todavía.</p>'}</div><div class="actions">${button('Agregar producto',"openMenuForm('product')")}${button('Agregar categoría',"openMenuForm('category')",'secondary')}</div>${menuForm==='category'?`<div class="card"><h2>Agregar categoría</h2><label>Nombre de la categoría</label><input id="newCategory" oninput="menuDirty=true" placeholder="Ejemplo: Desayunos"><div class="actions">${button('Guardar categoría','addCategory()')}${button('Cancelar',"openMenuForm('')",'secondary')}</div></div>`:menuForm==='product'?`<div class="card"><h2>Agregar producto</h2><label>Categoría</label><select id="productCategory" onchange="menuDirty=true">${s.categories.map(c=>`<option value="${c.id}" ${menuCategory===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label>Nombre del producto</label><input id="newProduct" oninput="menuDirty=true"><label>Descripción (opcional)</label><input id="newDescription" oninput="menuDirty=true"><label>Precio de venta (${s.config.currency})</label><input id="newPrice" type="number" min="0.01" step="0.01" oninput="menuDirty=true"><label>Existencia inicial (piezas, opcional)</label><input id="newStock" type="number" min="0" step="1" oninput="menuDirty=true"><p class="muted">Es un conteo inicial; todavía no se descuenta al vender.</p><div class="actions">${button('Guardar producto','addProduct()')}${button('Cancelar',"openMenuForm('')",'secondary')}</div></div>`:''}`;}
let menuDirty=false;
function openMenuForm(value){if(busy)return;if(menuDirty&&!globalThis.confirm('Hay datos sin guardar. ¿Descartar este formulario?'))return;menuDirty=false;menuForm=value;render();}
function selectMenuCategory(id){if(busy)return;if(menuDirty&&!globalThis.confirm('Hay datos sin guardar. ¿Cambiar categoría y descartar el formulario?'))return;menuDirty=false;menuForm='';menuCategory=id;render();}
async function addCategory(){const name=$('newCategory').value.trim();if(!name){note('Escribe el nombre de la categoría.');return;}const category={id:token(),name};await commit(draft=>{if(draft.categories.some(c=>c.name.toLocaleLowerCase('es')===name.toLocaleLowerCase('es')))throw Error('Esa categoría ya existe.');draft.categories.push(category);},()=>{menuCategory=category.id;menuForm='';menuDirty=false;},'Categoría guardada.');}
async function addProduct(){const name=$('newProduct').value.trim(),raw=$('newPrice').value,price=Math.round(Number(raw)*100),categoryId=$('productCategory').value,description=$('newDescription').value.trim();if(!name||!/^\d+(\.\d{1,2})?$/.test(raw)||!Number.isSafeInteger(price)||price<=0){note('Revisa nombre y precio positivo con hasta dos decimales.');return;}const stockRaw=$('newStock').value.trim();if(stockRaw&&!/^\d+$/.test(stockRaw)||stockRaw&&!Number.isSafeInteger(Number(stockRaw))){note('La existencia debe ser un número entero de piezas, cero o mayor.');return;}const producto={id:token(),name,price,categoryId,description,initialStock:stockRaw===''?null:Number(stockRaw),stockCountedAt:stockRaw===''?null:new Date().toISOString()};await commit(draft=>{if(!draft.categories.some(c=>c.id===categoryId))throw Error('Selecciona una categoría.');draft.products.push(producto);},()=>{menuCategory=categoryId;menuForm='';menuDirty=false;},'Producto guardado en este dispositivo.');}
function reportsScreen(){let x;try{x=CafeDemo.report(s,reportFilters);}catch(e){return title('Reportes','Revisa las fechas')+'<p>'+esc(e.message)+'</p>'+button('Quitar filtros','clearReport()');}const f=reportFilters;return title('Revisar la operación','Ventas, cobros y cuentas')+`<div class="summary three"><div class="card"><span class="muted">Vendido</span><div class="total">${money(x.sales)}</div></div><div class="card"><span class="muted">Cobrado</span><div class="total">${money(x.receipts)}</div></div><div class="card"><span class="muted">Crédito pendiente</span><div class="total">${money(x.debt)}</div></div></div><p class="muted">Vendido y cobrado corresponden a los movimientos filtrados. Crédito pendiente es la deuda acumulada hasta la fecha final: incluye cargos anteriores y descuenta pagos y anticipos. El tipo de movimiento y la fecha inicial no cambian esa deuda.</p><div class="card"><h2>Filtrar reporte</h2><label>Nivel educativo</label><select id="reportLevel">${levelOptions(f.level,true)}</select><div class="two"><div><label>Desde</label><input id="reportFrom" type="date" value="${esc(f.from||'')}"></div><div><label>Hasta</label><input id="reportTo" type="date" value="${esc(f.to||'')}"></div><div><label>Grado</label><select id="reportGrade"><option value="">Todos</option>${[1,2,3,4,5,6].map(g=>`<option value="${g}" ${f.grade===String(g)?'selected':''}>${g}°</option>`).join('')}</select></div><div><label>Grupo</label><select id="reportGroup"><option value="">Todos</option>${['A','B','C','D','E','F'].map(g=>`<option ${f.group===g?'selected':''}>${g}</option>`).join('')}</select></div></div><label>Buscar por nombre o apellidos</label><input id="reportSearch" value="${esc(f.search||'')}" placeholder="Escribe parte del nombre o apellidos" oninput="filterStudentOptions(this.value)"><label>Alumno / cliente</label><select id="reportStudent">${studentOptions(f.search||'')}</select><label>Tipo de movimiento</label><select id="reportKind"><option value="">Todos</option>${[['cash','Venta pagada'],['sale','Venta a cuenta'],['payment','Pago / anticipo'],['reverse','Anulación'],['refund-credit','Devolución de anticipo'],['refund-cash','Devolución de venta'],['opening','Saldo inicial']].map(([v,l])=>`<option value="${v}" ${f.kind===v?'selected':''}>${l}</option>`).join('')}</select><div class="actions">${button('Aplicar filtros','applyReport()')}${button('Quitar filtros','clearReport()','secondary')}</div></div><div class="card"><h2>Movimientos · ${x.events.length}</h2>${x.events.map(e=>`<div class="row"><span>${esc(CafeDemo.eventLabel(e,s))}<br><span class="muted">${esc(e.date)} · ${e.student?esc(s.students.find(a=>a.id===e.student).name):'Sin alumno'}</span></span><strong>${money(e.total)}</strong></div>${['cash','sale','payment','opening'].includes(e.kind)&&!CafeDemo.reversed(s,e.id)?button('Corregir / anular',`startCorrection('${e.id}')`,'plain'):''}${e.kind==='cash'&&CafeDemo.reversed(s,e.id)?button('Revisar devolución',`startRefund('cash','${e.id}')`,'plain'):''}`).join('')||'<p class="muted">Sin movimientos con estos filtros.</p>'}</div><div class="card"><h2>Cuentas de alumnos</h2><p class="muted">Saldos al ${f.to?esc(f.to):'momento actual'}. Abrir una cuenta muestra el saldo actual y permite registrar pagos o preparar su documento.</p><label>Mostrar cuentas</label><select onchange="accountFilter=this.value;render()"><option value="pending">Con deuda</option><option value="all" ${accountFilter==='all'?'selected':''}>Todos</option><option value="credit" ${accountFilter==='credit'?'selected':''}>Con saldo a favor</option></select>${x.accounts.filter(a=>accountFilter==='all'||(accountFilter==='credit'?a.balance<0:a.balance>0)).map(({student:a,balance:b})=>`<button class="student" onclick="openAccount('${a.id}')"><strong>${esc(a.name)}</strong><br><span>${esc(studentGroup(a))}${a.archived?' · Retirado':''} · ${saldo(b)}</span></button>`).join('')||'<p class="muted">Sin cuentas con este filtro.</p>'}</div><p class="notice">Las ventas sin alumno no aparecen al filtrar por alumno, nivel, grado o grupo. Cada hermano conserva su cuenta y documento.</p>`;}
function studentOptions(search){const query=search.trim().toLocaleLowerCase('es');return '<option value="">Todos los alumnos / sin alumno</option>'+s.students.filter(a=>a.id===reportFilters.student||a.name.toLocaleLowerCase('es').includes(query)).map(a=>`<option value="${a.id}" ${reportFilters.student===a.id?'selected':''}>${esc(a.name)} · ${esc(studentGroup(a))}</option>`).join('');}
function filterStudentOptions(search){$('reportStudent').innerHTML=studentOptions(search);}
function applyReport(){const f={level:$('reportLevel').value,from:$('reportFrom').value,to:$('reportTo').value,grade:$('reportGrade').value,group:$('reportGroup').value,student:$('reportStudent').value,search:$('reportSearch').value,kind:$('reportKind').value};try{CafeDemo.report(s,f);}catch(e){note(e.message);return;}reportFilters=f;render();note('Filtros aplicados.');}
function clearReport(){reportFilters={};render();note('Reporte sin filtros.');}
function operationDate(){return new Intl.DateTimeFormat('es-MX',{dateStyle:'medium',timeZone:s.config.timezone}).format(new Date());}

function gradeGroupFields(a){return `<div class="two"><div><label>Grado</label><select id="editGrade"><option value="">Seleccionar grado</option>${[1,2,3,4,5,6].map(g=>`<option value="${g}" ${a.grade===g?'selected':''}>${g}°</option>`).join('')}</select></div><div><label>Grupo</label><select id="editGroup"><option value="">Seleccionar grupo</option>${['A','B','C','D','E','F'].map(g=>`<option ${a.groupLetter===g?'selected':''}>${g}</option>`).join('')}</select></div></div>`;}
function editStudent(id){if(busy)return;selected=id;editingStudent=id;tab='EditarAlumno';render();note('');}
function studentEditScreen(){const a=s.students.find(x=>x.id===editingStudent);return title('Alumnos','Editar alumno')+(!s.events.some(e=>e.student===a.id&&!(e.kind==='opening'&&CafeDemo.reversed(s,e.id)||e.kind==='reverse'&&s.events.find(t=>t.id===e.target)?.kind==='opening'))&&a.opening===0?button('Registrar saldo inicial de libreta',`startOpening('${a.id}')`,'secondary'):'')+`<label>Nombre(s)</label><input id="editFirstName" value="${esc(a.firstName??a.name)}"><label>Apellidos</label><input id="editSurnames" value="${esc(a.surnames||'')}"><label>Nivel educativo</label><select id="editLevel">${levelOptions(a.level)}</select>${gradeGroupFields(a)}<p class="muted">Los movimientos y el saldo se conservan. Para nombres anteriores, separa aquí los apellidos.</p><div class="actions">${button('Guardar cambios','saveStudentDetails()')}${button('Cancelar',"nav('Alumnos')",'secondary')}</div>`;}
function editProduct(id){if(busy)return;editingProduct=id;tab='EditarProducto';render();note('');}
function productEditScreen(){const p=s.products.find(x=>x.id===editingProduct);return title('Menú','Editar producto')+`<label>Nombre</label><input id="editProductName" value="${esc(p.name)}"><label>Descripción (opcional)</label><input id="editDescription" value="${esc(p.description)}"><label>Categoría</label><select id="editCategory">${s.categories.map(c=>`<option value="${c.id}" ${p.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label>Precio de venta (${s.config.currency})</label><input id="editPrice" type="number" min="0.01" step="0.01" value="${(p.price/100).toFixed(2)}"><p class="muted">El nuevo precio se aplica a las próximas ventas. Las ventas guardadas conservan su precio original.</p><div class="actions">${button('Guardar cambios','saveProductDetails()')}${button('Cancelar',"nav('Menú')",'secondary')}</div>`;}
async function saveProductDetails(){const id=editingProduct,name=$('editProductName').value.trim(),description=$('editDescription').value.trim(),categoryId=$('editCategory').value,raw=$('editPrice').value,price=Math.round(Number(raw)*100);if(!name||!/^\d+(\.\d{1,2})?$/.test(raw)||!Number.isSafeInteger(price)||price<=0){note('Revisa nombre y precio positivo con hasta dos decimales.');return;}await commit(d=>{const p=d.products.find(x=>x.id===id);if(!p||p.archived)throw Error('Producto no disponible.');if(!d.categories.some(c=>c.id===categoryId))throw Error('Selecciona una categoría.');Object.assign(p,{name,description,categoryId,price});},()=>{tab='Menú';delete cart[id];},'Producto actualizado. Se retiró del carrito pendiente; puedes agregarlo con su precio nuevo.');}
function requestRemove(kind,id){if(busy)return;removing={kind,id};tab='Eliminar';render();note('');}
function removeScreen(){const list=removing.kind==='product'?s.products:s.students,a=list.find(x=>x.id===removing.id),b=removing.kind==='student'?CafeDemo.balance(s,a.id):0;return title('Revisar antes de continuar','Eliminar '+(removing.kind==='product'?'producto':'alumno'))+`<div class="card"><h2>${esc(a.name)}</h2><p>Se retirará de la lista activa. Su historial se conserva y podrás restaurarlo desde Ajustes.</p>${removing.kind==='student'?`<p>Cuenta: <strong>${saldo(b)}</strong>. Sigue disponible en Reportes para consultar y cobrar.</p>`:''}</div><div class="actions">${button('Confirmar eliminación','confirmRemove()','danger')}${button('Cancelar',removing.kind==='product'?"nav('Menú')":"nav('Alumnos')",'secondary')}</div>`;}
async function confirmRemove(){const {kind,id}=removing;await commit(d=>{const a=(kind==='product'?d.products:d.students).find(x=>x.id===id);if(!a)throw Error('Registro no encontrado.');a.archived=true;},()=>{delete cart[id];if(selected===id)selected=activeStudents()[0]?.id;tab=kind==='product'?'Menú':'Alumnos';removing=null;},'Retirado de la lista activa. Historial conservado.');}
async function restoreItem(kind,id){await commit(d=>{const a=(kind==='product'?d.products:d.students).find(x=>x.id===id);if(!a)throw Error('Registro no encontrado.');a.archived=false;},()=>{},'Registro restaurado.');}
function archivedScreen(){return `<div class="card"><h2>Registros retirados</h2><p class="muted">Conservamos sus cuentas y ventas. Restaurar permite volver a usarlos.</p>${s.students.filter(a=>a.archived).map(a=>`<div class="catalog-item">Alumno · ${esc(a.name)} · ${esc(studentGroup(a))}${button('Restaurar',`restoreItem('student','${a.id}')`,'secondary')}</div>`).join('')}${s.products.filter(p=>p.archived).map(p=>`<div class="catalog-item">Producto · ${esc(p.name)}${button('Restaurar',`restoreItem('product','${p.id}')`,'secondary')}</div>`).join('')||(!s.students.some(a=>a.archived)?'<p class="muted">Sin registros retirados.</p>':'')}</div>`;}

function settingsScreen(){const c=s.config;return title('Cafetería · beta 0.7.0','Configuración')+`<p class="notice">Beta de prueba: valida primero el acceso y la recuperación en IONOS. Usa datos ficticios hasta comprobar bloqueo local, reapertura offline y corte de caja.</p><label>Nombre de la cafetería</label><input id="businessName" value="${esc(c.name)}" placeholder="Nombre de tu cafetería de prueba"><label>Escuela (opcional)</label><input id="schoolName" value="${esc(c.school)}" placeholder="Nombre de la escuela"><label>Ubicación (opcional)</label><input id="locationName" value="${esc(c.location)}" placeholder="Ciudad, colonia o dirección"><label>Moneda</label><select id="currency" ${s.events.length?'disabled':''}>${['MXN','USD'].map(x=>`<option ${c.currency===x?'selected':''}>${x}</option>`).join('')}</select><label>Zona horaria</label><select id="timezone" ${s.events.length?'disabled':''}>${['America/Mexico_City','America/Chicago','America/New_York','America/Los_Angeles'].map(x=>`<option ${c.timezone===x?'selected':''}>${x}</option>`).join('')}</select><label>Ciclo escolar</label><input id="cycle" value="${esc(c.cycle)}" placeholder="Ejemplo: 2026–2027"><div class="actions">${button('Guardar configuración','saveSettings()')}</div><div class="card"><h2>Datos en este dispositivo</h2><p>${s.students.length} alumnos · ${s.products.length} productos · ${s.events.length} movimientos</p><p>Versión de datos: ${revision}</p><p id="cloudStatus" role="status">${esc(cloudMessage)}</p><div class="actions">${button('Respaldar ahora','backupNow()','secondary')}${button('Recuperar desde IONOS','inspectCloud()','secondary')}</div><div id="cloudPreview"></div></div>${button('Bloquear este teléfono','lockLocal()','secondary')}${button('Cerrar sesión IONOS','logoutCloud()','secondary')}${archivedScreen()}${backupScreen()}${button('Proteger guardado local','protectStorage()','secondary')}<p class="muted">Un teléfono de captura. El guardado depende de este navegador; borrar sus datos elimina esta copia. Moneda y zona horaria se fijan al registrar el primer movimiento.</p>`;}
async function saveSettings(){const name=$('businessName').value.trim(),currency=$('currency').value,timezone=$('timezone').value,cycle=$('cycle').value.trim(),school=$('schoolName').value.trim(),location=$('locationName').value.trim();if(!name||!cycle){note('Escribe nombre y ciclo escolar.');return;}await commit(draft=>{if(draft.events.length&&(currency!==draft.config.currency||timezone!==draft.config.timezone))throw Error('La moneda y zona horaria ya tienen movimientos.');draft.config={name,school,location,currency,timezone,cycle,initialized:true};},()=>{tab='Menú';},'Configuración guardada. Ahora agrega productos.');}
let localStore=globalThis.__CAFE_TEST_MODE__?CafeStorage.create(globalThis.indexedDB):null;
function status(t){$('saveStatus').textContent=t;}
async function commit(change,after,message){
 if(!ready||busy)return;busy=true;status('Guardando…');
 try{if(captureBlocked)throw Error('Este equipo ya no puede capturar. Recupera desde IONOS.');if(globalThis.CafeBoot){if(!cloud)throw Error('Control del equipo no disponible.');await cloud.guard();}const result=await localStore.update(change,CafeDemo.seed,revision);s=result.state;revision=result.revision;if(cloudRestoreHead!==null){restoreCandidate=null;cloudRestoreHead=null;cloud?.resume();}after();render();note(result.changed?message:'La operación ya estaba guardada.');status('Guardado en este dispositivo');cloud?.queue();}
 catch(e){note('No se guardó: '+e.message);status('Error de guardado · vuelve a intentar');}
 finally{busy=false;}
}
async function protectStorage(){try{const ok=await globalThis.navigator?.storage?.persist?.();note(ok?'El navegador concedió protección de almacenamiento. Aún falta el respaldo.':'El navegador no concedió protección. El respaldo sigue pendiente.');}catch(e){note('No se pudo solicitar protección de almacenamiento.');}}
async function initialize(){status('Abriendo datos…');if(!globalThis.CafeBoot&&!globalThis.__CAFE_TEST_MODE__){status('Captura detenida');$('screen').innerHTML='<h1>No se pudo preparar el acceso seguro</h1><p>No se abrió ningún dato. Recarga la app actualizada.</p>';return;}if(globalThis.CafeBoot){try{globalThis.CafeServer=await CafeBoot.context();localStore=CafeVault.create(globalThis.indexedDB,CafeServer.database,CafeDemo.seed,CafeStorage.validate);await showLocalGate();}catch(e){$('screen').innerHTML=title('Abrir mi cafetería','Se necesita acceso')+'<p>'+esc(e.message)+'</p><a href="./index.php">Entrar a IONOS</a>';status('Datos bloqueados');}return;}
 try{const r=await localStore.load(CafeDemo.seed);s=r.state;revision=r.revision;selected=activeStudents()[0]?.id;ready=true;tab=s.config.initialized?'Venta':'Ajustes';render();status('Guardado local disponible');startCloud();}
 catch(e){storageError=e.message;status('Guardado no disponible');$('screen').innerHTML=title('No se pudo abrir el guardado','Captura detenida')+'<p>'+esc(storageError)+'</p><p>No se han reemplazado los datos existentes. Vuelve a abrir esta app en el mismo navegador.</p>';}
}
const initialized=initialize();

let cashToken='',moveToken='',correctionId='',correctionToken='',refundKind='',refundTarget='',refundToken='',openingStudent='',openingToken='';
function cashStatus(){const x=CafeDemo.active(s);return `<p class="cash-strip">${x?'Caja abierta · Fondo '+money(x.fund):'Caja cerrada. Abre caja para registrar ventas.'} ${button(x?'Ver caja':'Abrir caja',"nav('Caja')",'secondary')}</p>`;}
function cashScreen(){const x=CafeDemo.active(s);if(!x){cashToken||=token();return title('Control de efectivo','Abrir caja')+`<label>Fondo inicial para dar cambio (${s.config.currency})</label><input id="cashFund" type="number" min="0" step="0.01" placeholder="Puede ser cero"><p class="muted">Este fondo no es una venta ni un cobro.</p>${button('Confirmar apertura','openCashUI()')}<h2>Cortes guardados</h2>${s.sessions.filter(x=>x.closedAt).slice().reverse().map(x=>`<div class="card"><strong>${esc(x.closedAt.slice(0,10))}</strong><p>Esperado: ${money(x.snapshot.expected)} · Contado: ${money(x.counted)} · Diferencia: ${money(x.difference)}</p></div>`).join('')||'<p class="muted">Sin cortes todavía.</p>'}`;}
 const t=CafeDemo.cashSummary(s,x.id);moveToken||=token();return title('Control de efectivo','Caja abierta')+`<p>Apertura: ${esc(new Date(x.openedAt).toLocaleString('es-MX',{timeZone:s.config.timezone}))}</p>${CafeDemo.day({occurredAt:x.openedAt},s.config.timezone)!==CafeDemo.day({occurredAt:new Date().toISOString()},s.config.timezone)?'<p class="notice">Esta caja viene de otro día. Revísala y ciérrala antes de iniciar otra jornada si corresponde.</p>':''}<div class="card"><div class="row"><span>Fondo inicial</span><strong>${money(x.fund)}</strong></div><div class="row"><span>Vendido neto en esta caja</span><strong>${money(t.sales)}</strong></div><div class="row"><span>Ventas a cuenta (brutas)</span><strong>${money(t.creditSales)}</strong></div><div class="row"><span>Cobrado neto</span><strong>${money(t.receipts)}</strong></div><div class="row"><span>Transferencias netas</span><strong>${money(t.transfers)}</strong></div><div class="row"><strong>Efectivo esperado</strong><span class="total">${money(t.expected)}</span></div></div>${t.pendingRefunds?'<p class="notice">Devoluciones de ventas anuladas pendientes de entregar: '+money(t.pendingRefunds)+'. Revísalas en Reportes.</p>':''}<details class="card"><summary>Registrar entrada / retiro de efectivo</summary><label>Tipo</label><select id="cashDirection"><option value="in">Agregar fondo</option><option value="out">Retirar efectivo</option></select><label>Importe</label><input id="cashMoveAmount" type="number" min="0.01" step="0.01"><label>Motivo</label><input id="cashMoveReason">${button('Revisar y guardar movimiento','moveCashUI()')}</details><div class="card"><h2>Cerrar caja</h2><label>Efectivo contado</label><input id="cashCounted" type="number" min="0" step="0.01"><p class="muted">Cuenta los billetes y monedas. La diferencia queda registrada; el saldo de los alumnos no cambia.</p>${button('Revisar corte','closeCashUI()')}</div><details class="card"><summary>Entradas y retiros</summary>${s.cashMoves.filter(e=>e.sessionId===x.id).map(e=>`<p>${e.direction==='in'?'+':'−'}${money(e.total)} · ${esc(e.reason)}</p>`).join('')||'Sin movimientos adicionales.'}</details>`;}
async function openCashUI(){let fund;try{fund=cents($('cashFund').value,true);}catch(e){note(e.message);return;}const cmd={id:cashToken,fund,openedAt:new Date().toISOString()};await commit(d=>CafeDemo.openCash(d,cmd),()=>{cashToken='';moveToken='';},'Caja abierta.');}
async function moveCashUI(){let n;try{n=cents($('cashMoveAmount').value);}catch(e){note(e.message);return;}const reason=$('cashMoveReason').value.trim(),direction=$('cashDirection').value,x=CafeDemo.active(s);if(!reason){note('Escribe el motivo.');return;}if(!globalThis.confirm(`${direction==='in'?'Agregar':'Retirar'} ${money(n)}. Motivo: ${reason}. ¿Confirmar?`))return;const cmd={id:moveToken,sessionId:x.id,total:n,direction,reason,occurredAt:new Date().toISOString()};await commit(d=>CafeDemo.moveCash(d,cmd),()=>{moveToken='';},'Movimiento de caja guardado.');}
async function closeCashUI(){let n;try{n=cents($('cashCounted').value,true);}catch(e){note(e.message);return;}const x=CafeDemo.active(s),t=CafeDemo.cashSummary(s,x.id);if(!globalThis.confirm(`Esperado: ${money(t.expected)}. Contado: ${money(n)}. Diferencia: ${money(n-t.expected)}. ¿Confirmar cierre?`))return;await commit(d=>CafeDemo.closeCash(d,x.id,n,new Date().toISOString()),()=>{cashToken='';},'Corte de caja guardado.');}
function startCorrection(id){if(busy)return;correctionId=id;correctionToken=token();tab='Correccion';render();}
function correctionScreen(){const e=s.events.find(e=>e.id===correctionId);return title('Historial de operaciones','Anular registro')+`<div class="card"><p>${esc(CafeDemo.eventLabel(e,s))} · ${esc(e.date)}</p><strong>${money(e.total)}</strong><p>El original se conserva. La anulación lleva fecha y motivo. Después puedes registrar la operación correcta.</p>${e.kind==='cash'?'<p class="notice">Anular esta venta no afirma que devolviste dinero. Quedará pendiente registrar la devolución real.</p>':e.kind==='payment'?'<p class="notice">Esta acción corrige un pago capturado por error; no entrega dinero al cliente. Para devolver saldo a favor usa su cuenta.</p>':''}</div><label>Motivo</label><input id="correctionReason"><div class="actions">${button('Confirmar anulación','finishCorrection()','danger')}${button('Cancelar',"nav('Reportes')",'secondary')}</div>`;}
async function finishCorrection(){const reason=$('correctionReason').value.trim();if(!reason){note('Escribe el motivo.');return;}if(!CafeDemo.active(s)){note('Abre caja antes de registrar una corrección.');return;}const e={id:correctionToken,kind:'reverse',target:correctionId,reason,sessionId:CafeDemo.active(s).id,date:operationDate(),occurredAt:new Date().toISOString()};await commit(d=>CafeDemo.post(d,e),()=>{tab='Reportes';},'Anulación guardada; el original permanece en el historial.');}
function startRefund(kind,id){if(busy)return;refundKind=kind;refundTarget=id;refundToken=token();tab='Devolucion';render();}
function refundScreen(){const e=s.events.find(e=>e.id===refundTarget),limit=refundKind==='credit'?Math.max(0,-CafeDemo.balance(s,refundTarget)):e.total-CafeDemo.sum(s.events.filter(x=>x.kind==='refund-cash'&&x.target===e.id).map(x=>x.total));return title('Entrega manual de dinero','Registrar devolución')+`<p>Disponible para devolver: <strong>${money(limit)}</strong></p><label>Importe entregado</label><input id="refundAmount" type="number" min="0.01" step="0.01">${refundKind==='credit'?methodFields('refundMethod','cash'):`<p>Método original: ${e.method==='cash'?'Efectivo':e.method==='transfer'?'Transferencia':'Sin registrar; no se puede devolver desde este registro antiguo.'}</p>`}<label>Motivo / referencia</label><input id="refundReason"><p class="notice">Confirma solo después de entregar el efectivo o realizar y verificar la transferencia. La app no transfiere dinero.</p><div class="actions">${button('Confirmar dinero entregado','finishRefund()')}${button('Cancelar',"nav('Reportes')",'secondary')}</div>`;}
async function finishRefund(){if(!CafeDemo.active(s)){note('Abre caja antes de devolver dinero.');return;}let n;try{n=cents($('refundAmount').value);}catch(e){note(e.message);return;}const t=s.events.find(e=>e.id===refundTarget),event={id:refundToken,kind:refundKind==='credit'?'refund-credit':'refund-cash',student:refundKind==='credit'?refundTarget:t.student,target:refundKind==='cash'?refundTarget:null,total:n,method:refundKind==='credit'?$('refundMethod').value:t.method,reason:$('refundReason').value.trim(),delivered:true,sessionId:CafeDemo.active(s).id,date:operationDate(),occurredAt:new Date().toISOString()};await commit(d=>CafeDemo.post(d,event),()=>{tab='Reportes';},'Entrega de dinero registrada.');}
function startOpening(id){openingStudent=id;openingToken=token();tab='SaldoInicial';render();}
function openingScreen(){const a=s.students.find(a=>a.id===openingStudent);return title('Migrar libreta',esc(a.name))+`<label>Tipo de saldo anterior</label><select id="openingDirection"><option value="debt">Deuda por cobrar</option><option value="credit">Saldo a favor / anticipo</option></select><label>Importe</label><input id="openingAmount" type="number" min="0.01" step="0.01"><label>Motivo / referencia de libreta</label><input id="openingReason"><p class="notice">No cuenta como una venta o un cobro de hoy. Se registra antes del primer movimiento de este alumno.</p>${button('Confirmar saldo inicial','finishOpening()')}${button('Cancelar',"nav('Alumnos')",'secondary')}`;}
async function finishOpening(){let n;try{n=cents($('openingAmount').value);}catch(e){note(e.message);return;}const e={id:openingToken,kind:'opening',student:openingStudent,total:n,direction:$('openingDirection').value,reason:$('openingReason').value.trim(),date:operationDate(),occurredAt:new Date().toISOString()};await commit(d=>CafeDemo.post(d,e),()=>{tab='Alumnos';},'Saldo inicial documentado.');}

let restoreCandidate=null,restorePreviewRevision=0,backupWorking=false;
function backupScreen(){return `<details class="card"><summary>Respaldo manual cifrado y recuperación</summary><p class="notice">El archivo se cifra; la copia del navegador se protege con su clave local. Esta copia manual es independiente del respaldo IONOS. Conserva la contraseña: sin ella no se puede abrir este archivo.</p><label>Contraseña del respaldo (mínimo 12 caracteres)</label><input id="backupPassword" type="password" autocomplete="new-password"><div class="actions">${button('Descargar respaldo cifrado','exportBackup()','secondary')}</div><label>Archivo para restaurar</label><input id="restoreFile" type="file" accept=".json,application/json"><div class="actions">${button('Revisar archivo antes de restaurar','inspectBackup()','secondary')}</div><div id="restorePreview"></div></details><div class="card"><h2>Acceso y conexión</h2><p>Después de preparar con conexión, abre app.php con tu clave local incluso sin internet. El permiso de captura offline dura hasta 24 horas desde su última confirmación; después debes conectar. El respaldo requiere sesión de IONOS vigente.</p><p class="notice">Si otro teléfono tomó el control mientras este estaba sin red, se detectará al conectar. Detén siempre el anterior antes de cambiar equipo. Conserva la clave local; si se pierde, recupera desde IONOS en un navegador nuevo.</p></div>`;}
function downloadFile(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function exportBackup(){if(busy||backupWorking)return;backupWorking=true;try{const r=await localStore.load(CafeDemo.seed);if(r.revision!==revision)throw Error('Hay cambios en otra pestaña. Recarga antes de exportar.');const envelope=await CafeBackup.pack({schema:3,revision,state:JSON.parse(JSON.stringify(s))},$('backupPassword').value);downloadFile('cafeteria-respaldo-'+todayISO()+'.json',JSON.stringify(envelope),'application/json');$('backupPassword').value='';note('Archivo cifrado generado. Verifica que se descargó y guárdalo fuera del teléfono.');}catch(e){note('No se generó el respaldo: '+e.message);}finally{backupWorking=false;}}
async function inspectBackup(){if(busy||backupWorking)return;backupWorking=true;restoreCandidate=null;cloudRestoreHead=null;cloud?.resume();try{const f=$('restoreFile').files?.[0];if(!f||f.size>32000000)throw Error('Selecciona un respaldo de hasta 32 MB.');const imported=await CafeBackup.unpack(JSON.parse(await f.text()),$('backupPassword').value);CafeStorage.validate(imported);if(imported.schema!==3)throw Error('Formato anterior: genera el respaldo desde la versión actualizada.');restoreCandidate=imported;restorePreviewRevision=revision;const x=CafeDemo.summary(imported.state);$('restorePreview').innerHTML=`<div class="notice"><strong>${esc(imported.state.config.name)}</strong><p>${imported.state.students.length} alumnos · ${imported.state.products.length} productos · ${imported.state.events.length} movimientos · ${imported.state.documents.length} documentos.</p><p>Vendido neto: ${esc(new Intl.NumberFormat('es-MX',{style:'currency',currency:imported.state.config.currency}).format(x.sales/100))}</p><p>Reemplaza esta instalación; no suma movimientos. Detén el uso del teléfono anterior antes de recuperar en un sustituto.</p>${button('Confirmar reemplazo de datos','restoreBackup()','danger')}</div>`;note('Archivo abierto y validado. Todavía no se reemplazó ningún dato.');}catch(e){$('restorePreview').innerHTML='';note(e.message);}finally{backupWorking=false;}}
async function restoreBackup(){if(busy||!restoreCandidate)return;if(revision!==restorePreviewRevision){note('La instalación cambió después de revisar el archivo. Revisa de nuevo antes de restaurar.');return;}if(!globalThis.confirm('Se reemplazarán los datos de esta instalación por el respaldo revisado. ¿Confirmar?'))return;busy=true;status('Restaurando…');try{if(cloudRestoreHead!==null){if(!cloud)throw Error('El respaldo IONOS no está conectado.');const password=$('cloudPassword').value;if(!password)throw Error('Confirma tu contraseña de acceso.');const claimed=await cloud.claim(cloudRestoreHead,password);cloudRestoreHead=claimed.head;$('cloudPassword').value='';}const r=await localStore.restore(restoreCandidate,CafeDemo.seed,revision);s=r.state;revision=r.revision;if(cloudRestoreHead!==null){cloud.completeRecovery();captureBlocked=false;const writer=$('writerNotice');if(writer)writer.hidden=true;}cart={};doc=null;selected='';restoreCandidate=null;tab='Ajustes';render();note('Restauración completa. Revisa saldos y cortes antes de continuar.');status('Guardado local restaurado');cloudRestoreHead=null;cloud?.resume();}catch(e){note('No se completó la recuperación: '+e.message);}finally{busy=false;if(globalThis.CafeBoot&&ready)await verifyWriter();}}
async function prepareOffline(){await retirePublicCache();note('Cierra todas las pestañas y comprueba app.php en modo avión.');}
function startCloud(){if(!globalThis.CafeServer||!globalThis.CafeCloud){cloudMessage='Esta copia no está conectada al acceso privado de IONOS.';return;}retirePublicCache();globalThis.addEventListener?.('pageshow',e=>{if(e.persisted)globalThis.location.reload();});try{cloud=CafeCloud.create({context:CafeServer,getRecord:async()=>{const r=await localStore.load(CafeDemo.seed);CafeStorage.validate(r);return {schema:3,revision:r.revision,state:r.state};},store:globalThis.localStorage,grant:until=>localStore.grant?.(until),offlineAllowed:()=>localStore.offlineAllowed?.()||false,onRevoked:message=>{captureBlocked=true;const n=$('writerNotice');if(n){n.hidden=false;n.textContent='Captura detenida. '+message+' Puedes consultar o recuperar desde IONOS.';}},onStatus:message=>{cloudMessage=message;const statusNode=$('cloudStatus');if(statusNode)statusNode.textContent=message;const badge=$('cloudBadge');if(badge)badge.textContent=message;},request:body=>CafeCloud.transport(CafeServer,body),online:()=>globalThis.navigator?.onLine!==false});if(globalThis.CafeBoot){if(!globalThis.__cafeWriterEvents){globalThis.__cafeWriterEvents=true;globalThis.addEventListener?.('online',()=>verifyWriter());globalThis.setInterval?.(()=>{if(ready&&!busy&&!backupWorking)verifyWriter();},30000);globalThis.addEventListener?.('focus',()=>{if(ready&&!busy)verifyWriter();});}}else cloud.queue();}catch(e){cloudMessage='Respaldo pendiente · '+e.message;$('cloudBadge').textContent=cloudMessage;}}
async function retirePublicCache(){try{if(globalThis.navigator?.serviceWorker){const r=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});await r.update();}}catch(e){note('No se pudo preparar la apertura offline. Vuelve a intentar con conexión.');}}
async function backupNow(){if(!cloud){note(cloudMessage);return;}await cloud.flush();}
async function inspectCloud(){if(busy||backupWorking||!cloud)return;backupWorking=true;restoreCandidate=null;cloudRestoreHead=null;try{const r=await cloud.inspect();if(!r.record){cloud.resume();throw Error('Todavía no hay un respaldo en IONOS.');}CafeStorage.validate(r.record);restoreCandidate=r.record;restorePreviewRevision=revision;cloudRestoreHead=r.head;const st=r.record.state;$('cloudPreview').innerHTML=`<div class="notice"><strong>${esc(st.config.name)}</strong><p>${st.students.length} alumnos · ${st.products.length} productos · ${st.events.length} movimientos.</p><p>Respaldado: ${esc(r.savedAt)}. Reemplaza los datos de este teléfono. No suma movimientos.</p><p>Detén la captura en el teléfono anterior. Al confirmar, este equipo será el que pueda respaldar.</p><label>Contraseña de acceso para confirmar</label><input id="cloudPassword" type="password" autocomplete="current-password"><div class="actions">${button('Recuperar y usar este teléfono','restoreBackup()','danger')}${button('Cancelar','cancelCloudRestore()','secondary')}</div></div>`;note('Respaldo revisado. Todavía no se han reemplazado datos.');}catch(e){restoreCandidate=null;cloud?.resume();note('No se pudo revisar: '+e.message);}finally{backupWorking=false;}}
function cancelCloudRestore(){restoreCandidate=null;cloudRestoreHead=null;$('cloudPreview').innerHTML='';cloud?.resume();note('Recuperación cancelada. Datos actuales conservados.');}
async function logoutCloud(){if(busy||backupWorking||!globalThis.CafeServer)return;if(Object.keys(cart).length&&!globalThis.confirm('Hay una compra sin confirmar. ¿Cerrar sesión y descartarla?'))return;await cloud?.pause();try{if(cloud)await cloud.request('logout');else await CafeCloud.transport(CafeServer,{action:'logout'});$('screen').innerHTML='<h1>Sesión cerrada</h1>';$('nav').innerHTML='';globalThis.location.assign('./index.php');}catch(e){cloud?.resume();note('No se cerró la sesión: '+e.message);}}

async function showLocalGate(){ready=false;const existing=await localStore.exists();$('nav').innerHTML='';$('writerNotice').hidden=true;$('screen').innerHTML=title('Cafetería · datos protegidos',existing?'Desbloquear este teléfono':'Proteger este teléfono')+`<p>${existing?'Escribe la clave local para abrir tus datos.':'Crea una clave local de al menos 12 caracteres. Los datos existentes se cifrarán sin reiniciar tus registros. Esta clave puede ser distinta de tu contraseña IONOS.'}</p><label>Clave local</label><input id="localPassword" type="password" autocomplete="${existing?'current-password':'new-password'}">${existing?'':'<label>Repetir clave local</label><input id="localRepeat" type="password" autocomplete="new-password">'}<div class="actions">${button(existing?'Desbloquear':'Cifrar y abrir','unlockLocal()')}</div><p class="muted">La clave no se guarda ni se envía a IONOS. Si la olvidas, recupera el respaldo en un navegador limpio.</p><a href="./index.php">Entrar a IONOS / recuperar acceso</a>`;status('Datos bloqueados');const b=$('cloudBadge');if(b)b.textContent='Desbloquea este teléfono para continuar.';}
async function unlockLocal(){if(busy)return;busy=true;try{const existing=await localStore.exists(),password=$('localPassword').value;if(!existing&&globalThis.CafeServer.offline)throw Error('La primera preparación requiere internet y acceso IONOS.');if(!existing&&password!==$('localRepeat').value)throw Error('Las claves locales no coinciden.');const r=await localStore.unlock(password);s=r.state;revision=r.revision;cart=await localStore.takeDraft();selected='';captureBlocked=false;ready=true;tab=s.config.initialized?'Venta':'Ajustes';render();status('Datos desbloqueados · guardado cifrado');note('');startCloud();installLocalLock();}catch(e){note(e.message);}finally{busy=false;if(ready)await verifyWriter();}}
async function verifyWriter(){if(!cloud||!ready||busy)return;try{const client=cloud;await client.verify();if(ready&&cloud===client)client.queue();}catch(e){const n=$('cloudBadge');if(n)n.textContent='Captura pendiente de autorización · '+e.message;}}
async function lockLocal(automatic=false){if(!globalThis.CafeBoot)return;if(busy||backupWorking){note('Termina la operación antes de bloquear.');return;}if(!automatic&&Object.keys(cart).length&&!globalThis.confirm('La compra pendiente se conservará como borrador cifrado. ¿Bloquear?'))return;ready=false;await cloud?.pause();try{await localStore.saveDraft(cart);}catch(e){ready=true;cloud?.resume();note('No se bloqueó: '+e.message);return;}localStore.lock();cloud=null;s=CafeDemo.seed();cart={};doc=null;selected='';restoreCandidate=null;cloudRestoreHead=null;$('toast').textContent='';await showLocalGate();}
function installLocalLock(){if(globalThis.__cafeLockInstalled)return;globalThis.__cafeLockInstalled=true;globalThis.addEventListener?.('pagehide',()=>{localStore.lock();});globalThis.addEventListener?.('pageshow',e=>{if(e.persisted)globalThis.location.reload();});globalThis.document.addEventListener?.('visibilitychange',()=>{if(lockTimer)clearTimeout(lockTimer);if(document.hidden)lockTimer=setTimeout(()=>{if(ready&&!busy&&!backupWorking)lockLocal(true);},300000);});}
